"""Monte-Carlo confirmation of the exact moment polynomials at larger dimensions.

Exhaustive averaging over all 2^C(N,2) sign configurations is only feasible for
N <= 6.  This demo instead samples random symmetric coin-flip matrices and compares
the sample mean of tr(W^L) with the exact predictions

      E[tr(W^1)] = E[tr(W^3)] = E[tr(W^5)] = 0        (exactly, at every N)
      E[tr(W^2)] = N(N-1)                             (deterministic: zero variance)
      E[tr(W^4)] = N(N-1)(2N-3)
      E[tr(W^6)] = N(N-1)(5N^2-15N+11)

Only the standard library is used: traces are computed with exact integer matrix
multiplication, so the numbers printed are exact rational sample means.
"""

from __future__ import annotations

import random
from typing import List, Sequence


def sample_matrix(n: int, rng: random.Random) -> List[List[int]]:
    """A uniformly random symmetric +-1 matrix with zero diagonal."""
    mat = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            s = 1 if rng.random() < 0.5 else -1
            mat[i][j] = s
            mat[j][i] = s
    return mat


def mat_mul(a: Sequence[Sequence[int]], b: Sequence[Sequence[int]]) -> List[List[int]]:
    n = len(a)
    return [[sum(a[i][k] * b[k][j] for k in range(n)) for j in range(n)] for i in range(n)]


def trace_power(mat: Sequence[Sequence[int]], power: int) -> int:
    n = len(mat)
    acc = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    for _ in range(power):
        acc = mat_mul(acc, mat)
    return sum(acc[i][i] for i in range(n))


def exact_moment(n: int, power: int) -> int:
    if power % 2 == 1:
        return 0
    if power == 2:
        return n * (n - 1)
    if power == 4:
        return n * (n - 1) * (2 * n - 3)
    if power == 6:
        return n * (n - 1) * (5 * n * n - 15 * n + 11)
    raise ValueError("no closed form recorded for this power")


def main(samples: int = 400, seed: int = 20260821) -> None:
    rng = random.Random(seed)
    print(f"{samples} samples per dimension\n")
    header = f"{'N':>4}{'L':>4}{'sample mean tr(W^L)':>24}{'exact prediction':>20}{'rel. err':>12}"
    print(header)
    print("-" * len(header))
    for n in (4, 6, 8, 10):
        mats = [sample_matrix(n, rng) for _ in range(samples)]
        for power in (1, 2, 3, 4, 5, 6):
            mean = sum(trace_power(m, power) for m in mats) / samples
            exact = exact_moment(n, power)
            if exact == 0:
                err = abs(mean)
                errs = f"{err:>12.3f}"
            else:
                errs = f"{abs(mean - exact) / exact:>12.4f}"
            print(f"{n:>4}{power:>4}{mean:>24.3f}{exact:>20}{errs}")
        print()
    print("The second moment is deterministic: tr(W^2) = N(N-1) on every single sample.")
    for n in (4, 6, 8):
        vals = {trace_power(m, 2) for m in (sample_matrix(n, rng) for _ in range(50))}
        print(f"  N = {n}:  observed values {vals};  N(N-1) = {n*(n-1)}")


if __name__ == "__main__":
    main()

