function DICHOTOMY-CERTIFICATE(steps):
    for t, (a, b) in steps:
        if a = b then
            return (0, "step t is a loop; the factor W_aa is identically zero")
    mult <- multiset of canonical edges {a, b} over all steps
    odd  <- { p : mult[p] is odd }
    if odd is nonempty then
        p0 <- any element of odd
        return (0, "flip the sign of p0: a fixed-point-free involution that negates "
