algorithms.code:
"""Algorithm 3: Certifying the exact ensemble dichotomy by the sign-flip involution.

For a family of steps (a_t, b_t) the ensemble average of the monomial
prod_t W_{a_t b_t} over all 2^C(N,2) sign configurations is exactly 0 or 1.  Rather
than averaging over the exponentially many configurations, this routine produces a
*certificate*:

  * a loop  a_t = b_t                       -> value 0 (the monomial is identically 0);
  * an edge of odd multiplicity p_0         -> value 0, certified by the involution
                                               that flips the sign of p_0 and pairs
                                               configurations into cancelling pairs;
  * loop-free with all multiplicities even  -> value 1, certified by the observation
                                               that the monomial is the constant 1.

Cost: O(n) in the number of steps, versus O(2^C(N,2) * n) for brute force.
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

Edge = Tuple[int, int]
Step = Tuple[int, int]


def edge_of(u: int, v: int) -> Edge:
    return (u, v) if u <= v else (v, u)


def multiplicities(steps: Sequence[Step]) -> Dict[Edge, int]:
    mult: Dict[Edge, int] = {}
    for a, b in steps:
        e = edge_of(a, b)
        mult[e] = mult.get(e, 0) + 1
    return mult


def dichotomy_certificate(steps: Sequence[Step]) -> Tuple[int, str]:
    """Return (value, human-readable certificate) for E[prod_t W_{a_t b_t}]."""
    for t, (a, b) in enumerate(steps):
        if a == b:
            return 0, (
                f"step {t} is the loop ({a},{a}); the factor W_{{{a}{a}}} is identically "
                "zero, so the monomial vanishes for every configuration."
            )
    mult = multiplicities(steps)
    odd = [p for p, m in mult.items() if m % 2 == 1]
    if odd:
        p0 = min(odd)
        return 0, (
            f"edge {set(p0)} has odd multiplicity {mult[p0]}; flipping only its sign is a "
            "fixed-point-free involution of the configuration space under which the "
            "monomial changes sign, so configurations cancel in pairs."
        )
    detail = ", ".join(f"{set(p)}:{m}" for p, m in sorted(mult.items()))
    return 1, (
        "loop-free with all multiplicities even (" + detail + "); every factor is a "
        "square of a sign, so the monomial is the constant function 1."
    )


def involution_pairing(n: int, steps: Sequence[Step]) -> List[Tuple[int, int]]:
    """For an odd-multiplicity family, list the (value, flipped value) pairs produced
    by the sign-flip involution on a few configurations, exhibiting the cancellation."""
    from itertools import combinations, product

    if any(a == b for a, b in steps):
        return []
    pairs_list: List[Edge] = list(combinations(range(n), 2))
    mult = multiplicities(steps)
    odd = [p for p, m in mult.items() if m % 2 == 1]
    if not odd:
        return []
    p0 = min(odd)
    out: List[Tuple[int, int]] = []
    for signs in product((-1, 1), repeat=len(pairs_list)):
        g = dict(zip(pairs_list, signs))
        if g[p0] != 1:                     # take one representative per involution orbit
            continue
        flipped = dict(g)
        flipped[p0] = -1

        def value(cfg: Dict[Edge, int]) -> int:
            prod = 1
            for a, b in steps:
                prod *= cfg[edge_of(a, b)]
            return prod

        out.append((value(g), value(flipped)))
    return out


if __name__ == "__main__":
    families: List[Tuple[str, List[Step]]] = [
        ("W01 W10", [(0, 1), (1, 0)]),
        ("W01 W12", [(0, 1), (1, 2)]),
        ("W01 W12 W21 W10", [(0, 1), (1, 2), (2, 1), (1, 0)]),
        ("W01 W01 W01", [(0, 1)] * 3),
        ("W22 W01 W10", [(2, 2), (0, 1), (1, 0)]),
    ]
    for name, steps in families:
        value, reason = dichotomy_certificate(steps)
        print(f"{name:<22} -> {value}   ({reason})")
        pairs = involution_pairing(3, steps)
        if pairs:
            assert all(x + y == 0 for x, y in pairs)
            print(f"{'':<22}    involution pairs all cancel: {pairs[:4]} ...")
